import type { Metadata } from "next";
import SitemapShell, {
  sitemapColumnsClass,
  sitemapLinkClass,
  sitemapSectionHeadingClass,
} from "@/components/sitemap-directory/shell";
import {
  getSitemapDirectoryCategories,
  groupCategoryPages,
} from "@/services/sitemap/directory";

export const revalidate = 86400;

export const metadata: Metadata = {
  title: "Tour Categories Sitemap - TravelShop Booking",
  description:
    "All tour categories on TravelShop Booking — adventure, culture, luxury, family holidays and more, by destination.",
  alternates: {
    canonical: "https://travelshopbooking.com/sitemap/tour-categories",
  },
};

export default async function SitemapTourCategoriesPage() {
  const categories = await getSitemapDirectoryCategories();
  const groups = groupCategoryPages(categories);

  return (
    <SitemapShell
      title="Tour Categories"
      intro="Our travel themes, from adventure to luxury — each with its destination-specific category pages."
      crumbs={[
        { pageTitle: "Sitemap", pageUrl: "/sitemap" },
        { pageTitle: "Tour Categories", pageUrl: "/sitemap/tour-categories" },
      ]}
    >
      <div className="tw-flex tw-flex-col tw-gap-10">
        {groups.map((group) => (
          <section key={group.key}>
            <h2 className={sitemapSectionHeadingClass}>
              {group.headerItem ? (
                <a
                  href={`/${group.headerItem.pageUrl}`}
                  className="tw-text-inherit tw-no-underline hover:tw-text-[#854ec9] tw-transition-colors"
                >
                  {group.title}
                </a>
              ) : (
                group.title
              )}
            </h2>
            {group.items.length > 0 && (
              <ul className={`${sitemapColumnsClass} tw-mt-4`}>
                {group.items.map((item) => (
                  <li key={item.id}>
                    <a href={`/${item.pageUrl}`} className={sitemapLinkClass}>
                      {item.title}
                    </a>
                  </li>
                ))}
              </ul>
            )}
          </section>
        ))}
      </div>
    </SitemapShell>
  );
}
